package com.mushafi.app;
public final class ChallengeClientPolicyTest {
 private static void need(boolean b,String label){if(!b)throw new AssertionError(label);}
 public static void main(String[] args){String room="/v1/room/11111111-1111-4111-a111-111111111111";need(ChallengeClient.validMethod("GET","/v1/profile"),"read profile");need(ChallengeClient.validMethod("DELETE","/v1/profile"),"delete profile");need(!ChallengeClient.validMethod("POST","/v1/profile"),"no unsupported write");for(String p:new String[]{"/v1/rooms","/v1/join","/v1/queue",room+"/answer",room+"/start",room+"/leave"}){need(ChallengeClient.validMethod("POST",p),"allowed POST");need(!ChallengeClient.validMethod("GET",p),"no GET mutation");need(!ChallengeClient.validMethod("DELETE",p),"no DELETE mutation");}need(ChallengeClient.validMethod("GET",room),"read room");need(!ChallengeClient.validMethod("POST",room),"no implicit room mutation");need(!ChallengeClient.validMethod(null,room),"null method");need(!ChallengeClient.validMethod("GET",null),"null path");need(!ChallengeClient.validMethod("POST","https://example.com/v1/join"),"fixed API origin");need(!ChallengeClient.validMethod("GET","/v1/room/../profile"),"no traversal");System.out.println("PASS native challenge method/path policy: account actions, room reads, explicit mutations, null/traversal/external paths.");}
}
